  "track.fp.m.pure.diagramTitle": "Kết quả của hàm phụ thuộc vào đâu",
  "track.fp.m.pure.diagramDesc": "Đồng hồ, lời gọi hàm, giá trị nhận được và bài test",
  "track.fp.m.pure.n.world": "Đồng hồ và biến đếm",
  "track.fp.m.pure.n.call": "Lời gọi fee",
